import { useState } from "react";
import { CopyButton } from "@/registry/erbium/blocks/copy-button";
import {
  InputGroup,
  InputGroupInput,
  InputGroupAddon,
  InputGroupButton,
} from "@/registry/erbium/ui/input-group";

const Example = () => {
  const [value, setValue] = useState("https://erbium.dev");

  return (
    <InputGroup className="w-80">
      <InputGroupInput
        value={value}
        onChange={(event) => {
          setValue(event.target.value);
        }}
      />
      <InputGroupAddon align="inline-end">
        <CopyButton
          value={value}
          aria-label="Copy URL"
          render={<InputGroupButton size="icon-xs" />}
        />
      </InputGroupAddon>
    </InputGroup>
  );
};

export default Example;
